sql:
SELECT url FROM constructors WHERE constructorId = (
    SELECT constructorId FROM constructorResults WHERE raceId = 9 ORDER BY points DESC LIMIT 1
)

SELECT url FROM circuits WHERE circuitId = (
    SELECT circuitId FROM races WHERE year = 2009 AND name = 'Spanish Grand Prix'
)

SELECT 
    (
        (SELECT overall_rating FROM Player_Attributes WHERE player_api_id = 
            (SELECT player_api_id FROM Player WHERE player_name = 'Ariel Borysiuk')
        ) - 
        (SELECT overall_rating FROM Player_Attributes WHERE player_api_id = 
            (SELECT player_api_id FROM Player WHERE player_name = 'Paulin Puel')
        )
    ) * 100.0 / 
    (SELECT overall_rating FROM Player_Attributes WHERE player_api_id = 
        (SELECT player_api_id FROM Player WHERE player_name = 'Paulin Puel')
    ) AS percentage_increase
